contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 drugs) public payable {
        c.seedMarket(drugs); if (__ESBMC_reverted()) return;
        assert(c.initialized() && c.marketDrugs() == drugs);
    }
    receive() external payable {}
}

