// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 drugs) internal {
        try c.seedMarket(drugs) {} catch { return; }
        assertTrue(c.initialized() && c.marketDrugs() == drugs);
    }

    function testFuzz_run(uint256 drugs) public {
        _run(drugs);
    }

    receive() external payable {}
}
